mapper.select:
select M.chat_message_no, M.chat_channel_no, M.chat_message_sender, E.emp_name AS sender_name, M.chat_message_content, M.chat_message_type, M.chat_message_ctime, M.chat_message_utime, M.chat_message_deleted
from chat_message M left outer join project_member PM on M.chat_message_sender = PM.project_member_no left outer join emp E on PM.emp_no = E.emp_no
where M.chat_channel_no = #{channelNo}
order by M.chat_message_no desc
select * from ( select * from temp_list
where chat_message_no < #{lastMessageNo}
)
where rownum <= #{size}
order by chat_message_no asc

select count(*)
from chat_message M
where M.chat_channel_no = #{channelNo}



        and M.chat_message_no < #{lastMessageNo}
